import { Terminal, ansi } from "march/ui"

// kahve falı terminali: "fal" bir fal açar, "zar 3" üç zar atar; renkler ANSI ile, bekleme çarkı io.spinner ile
const FORTUNES = ["Yakında bir derleme yeşile dönecek", "Bir sinyal seni düşünüyor", "Üç vakte kadar bir PR birleşecek", "Kahvende bir ok işareti: ileri!"]
const pick = <T,>(list: readonly T[]) => list[Math.floor(Math.random() * list.length)]!
const wait = (ms: number) => new Promise((ok) => setTimeout(ok, ms))

export function FortuneTerminal() {
  return <Terminal prompt="falcı ☕ " height="14rem" welcome={["[info] fal yaz, fincan kapansın", "zar 3: üç zar at"]} commands={{
    fal: async (_a, io) => {
      const s = io.spinner("fincan soğuyor")
      await wait(500)
      s.done("fincan hazır")
      io.print(ansi.magenta(pick(FORTUNES)), { bold: true })
    },
    zar: { desc: "Zar atar", args: [{ name: "kac", type: "number", default: 1 }], run: (a, io) => {
      const dice = Array.from({ length: Number(a.args["kac"]) }, () => pick(["⚀", "⚁", "⚂", "⚃", "⚄", "⚅"]))
      io.print(ansi.yellow(dice.join(" ")))
    } },
  }} />
}

import { Terminal, Card, ansi } from "march/ui"

// destek ekibinin sipariş konsolu: "siparis ara 1042", "siparis liste --durum kargoda", "iade 1042"
type Order = { no: number; customer: string; total: number; status: string }
const ORDERS: Order[] = [
  { no: 1041, customer: "Ayşe K.", total: 249, status: "teslim" },
  { no: 1042, customer: "Mert D.", total: 1180, status: "kargoda" },
  { no: 1043, customer: "Deniz A.", total: 75, status: "hazırlanıyor" },
]
const tone = (s: string) => s === "teslim" ? ansi.green(s) : s === "kargoda" ? ansi.cyan(s) : ansi.yellow(s)
const row = (o: Order) => [String(o.no), o.customer, `${o.total} ₺`, tone(o.status)]

export function OrderConsole() {
  let $refunds = 0
  return <Card m:theme="night">
    <p sx={{ text: "sm", color: "muted" }}>İade edilen: {$refunds}</p>
    <Terminal prompt="destek › " height="16rem" label="Sipariş konsolu" welcome="[info] siparis liste · siparis ara <no> · iade <no>" commands={{
      siparis: { desc: "Siparişler", sub: {
        liste: { desc: "Listeler", options: { durum: { type: "string", desc: "duruma göre süz" } },
          run: (a, io) => io.table(ORDERS.filter((o) => !a.options["durum"] || o.status === a.options["durum"]).map(row), ["no", "müşteri", "tutar", "durum"]) },
        ara: { desc: "Bir siparişi gösterir", args: [{ name: "no", type: "number", required: true }],
          run: (a, io) => { const o = ORDERS.find((x) => x.no === a.args["no"]); if (o) io.json(o, 1); else io.error(`${a.args["no"]} numaralı sipariş yok`) } },
      } },
      iade: { desc: "İade başlatır", args: [{ name: "no", type: "number", required: true }], run: (a, io) => {
        const o = ORDERS.find((x) => x.no === a.args["no"])
        if (!o) { io.error("sipariş bulunamadı"); return }
        $refunds++
        io.success(`${o.no} için ${o.total} ₺ iade başlatıldı`)
      } },
    }} />
  </Card>
}

import { Terminal, Button, ansi, type TerminalApi } from "march/ui"

// Terminal'in bütün özellikleri: komutlar (alt komut, seçenek), istem, karşılama, geçmiş (persist), renk takımı,
// arka plan, imleç, yazı tipi, satır sınırı, yükseklik, ad, yanıp sönme, hazır komutlar, REPL (fallback),
// kendi metinlerin, sınıf, ref; altta yalnız okunur bir kayıt (readonly), üstteki her komutu oraya yazar
const SCHEMES = ["auto", "surface", "dark", "light"] as const

export function TerminalLab() {
  let $scheme = 0
  let log: TerminalApi | undefined
  let term: TerminalApi | undefined
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" on:click={() => $scheme = ($scheme + 1) % SCHEMES.length}>Takım: {SCHEMES[$scheme]}</Button>
      <Button size="sm" on:click={() => term?.exec("say merhaba")}>say merhaba</Button>
    </div>
    <Terminal
      commands={{
        say: { desc: "Yazdığını söyler", args: [{ name: "text", rest: true }], options: { loud: { alias: "l", desc: "büyük harf" } },
          run: (a, io) => { const t = String(a.args["text"] ?? ""); io.print(a.options["loud"] ? ansi.bold(t.toUpperCase()) : t); log?.print(`say ${t}`) } },
        math: { desc: "Hesap", sub: { add: { args: [{ name: "a", type: "number" }, { name: "b", type: "number" }], run: (a, io) => io.success(String(Number(a.args["a"]) + Number(a.args["b"]))) } } },
      }}
      prompt={() => `${SCHEMES[$scheme]}$ `}
      welcome={["[info] say, math add 2 3; komut olmayan satır hesaplanır: 6*7"]}
      persist="lab"
      scheme={() => SCHEMES[$scheme]}
      background={undefined}
      cursor="block"
      font="ui-monospace, monospace"
      maxLines={200}
      height="12rem"
      label="Laboratuvar çıktısı"
      blink={false}
      builtins
      fallback={(line, io) => { const m = /^(\d+)\s*([+*-])\s*(\d+)$/.exec(line); if (!m) { io.error(`anlaşılmadı: ${line}`); return } const [a, b] = [Number(m[1]), Number(m[3])]; io.info(`= ${m[2] === "+" ? a + b : m[2] === "*" ? a * b : a - b}`) }}
      labels={{ command: "Komut satırı", historySearch: "geçmişte ara", notFound: (n) => `${n}? yok` }}
      class="lab-term"
      ref={(api) => term = api}
    />
    <Terminal readonly label="Olay kaydı" height="5rem" scheme="dark" background="#1f1330" welcome="kayıt başladı" ref={(api) => log = api} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TerminalLab } from "./TerminalLab.tsx"

// TerminalLab'in testleri: kaydedince Testler sekmesinde çalışır
const run = async (s: ReturnType<typeof renderTest>, line: string) => {
  const input = await s.type("Komut satırı", line)
  input.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }))
  await s.flush(4)
}

test("say komutu yazar ve alttaki kayda düşer", async () => {
  const s = renderTest(() => <TerminalLab />)
  await run(s, "say --loud merhaba")
  expect(s.sees("MERHABA")).toBe(true)
  expect(s.find("Olay kaydı")?.textContent).toContain("say merhaba")
})

test("alt komut: math add 2 3 = 5", async () => {
  const s = renderTest(() => <TerminalLab />)
  await run(s, "math add 2 3")
  expect(s.find("Laboratuvar çıktısı")?.textContent).toContain("5")
})

test("komut değilse fallback hesaplar, anlaşılmazsa söyler", async () => {
  const s = renderTest(() => <TerminalLab />)
  await run(s, "6*7")
  expect(s.sees("= 42")).toBe(true)
  await run(s, "selam")
  expect(s.sees("anlaşılmadı: selam")).toBe(true)
})

test("takım düğmesi renk takımını ve istemi değiştirir", async () => {
  const s = renderTest(() => <TerminalLab />)
  expect(s.get(".lab-term")?.className).toContain("m-term-auto")
  await s.click("Takım: auto")
  expect(s.get(".lab-term")?.className).toContain("m-term-surface")
  expect(s.sees("surface$")).toBe(true)
})
